INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('upma', 'Upma', 'उपमा', 'उपमा', 'tamil', true, '{"breakfast"}', 10, 15, 'easy', 2, NULL, 240, 5, 34, 9, 2, 'Quick savory semolina porridge tempered with mustard seeds, curry leaves, and vegetables.', 'राई, कड़ी पत्ता और सब्ज़ियों के तड़के वाला जल्दी बनने वाला नमकीन सूजी का उपमा।', 'मोहरी, कढीपत्ता आणि भाज्यांच्या फोडणीचा झटपट तयार होणारा खमंग रव्याचा उपमा.', 'https://www.youtube.com/results?search_query=upma+recipe+South+Indian+style+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('rava-kesari', 'Rava Kesari', 'रवा केसरी', 'रवा केसरी', 'tamil', true, '{"breakfast"}', 5, 15, 'easy', 2, NULL, 350, 4, 50, 16, 0.5, 'Rich saffron-tinted semolina sweet garnished with cashews and raisins, a beloved Tamil Nadu breakfast treat.', 'काजू-किशमिश से सजा केसर रंग का मीठा सूजी का हलवा, तमिलनाडु का पसंदीदा नाश्ते का मिठाई।', 'काजू-मनुक्यांनी सजवलेला केशरी रंगाचा गोड रव्याचा शिरा, तमिळनाडूमधील आवडता नाश्त्याचा गोड पदार्थ.', 'https://www.youtube.com/results?search_query=rava+kesari+recipe+Tamil+style+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('uttapam', 'Uttapam', 'उत्तपम', 'उत्तपम', 'tamil', true, '{"breakfast"}', 480, 15, 'easy', 2, NULL, 250, 6, 38, 8, 2.5, 'Thick, spongy pancake made from dosa batter topped with onions, tomatoes, and chillies.', 'डोसा बैटर से बना मोटा, मुलायम पैनकेक, प्याज़, टमाटर और मिर्च से सजाकर बनाया जाता है।', 'डोसा पिठापासून बनवलेला जाड, मऊ पॅनकेक, कांदा, टोमॅटो आणि मिरचीने सजवून बनवला जातो.', 'https://www.youtube.com/results?search_query=uttapam+recipe+onion+tomato+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('adai', 'Adai', 'अडई', 'अडई', 'tamil', true, '{"breakfast","lunch"}', 240, 20, 'medium', 2, NULL, 270, 10, 36, 9, 5, 'Protein-rich crispy pancake made from a mixed lentil and rice batter, spiced with whole red chillies and curry leaves.', 'मिश्रित दाल और चावल के घोल से बना प्रोटीन भरपूर कुरकुरा चीला, साबुत लाल मिर्च और कड़ी पत्ते का स्वाद।', 'मिश्र डाळ आणि तांदळाच्या पिठापासून बनवलेला प्रथिनयुक्त कुरकुरीत धिरडे, लाल मिरची आणि कढीपत्त्याचा स्वाद.', 'https://www.youtube.com/results?search_query=adai+dosa+recipe+mixed+dal+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('dal-baati-churma', 'Dal Baati Churma', 'दाल बाटी चूरमा', 'दाल बाटी चूरमा', 'rajasthani', true, '{"lunch","dinner"}', 30, 60, 'medium', 2, 'roti', 650, 18, 78, 30, 8, 'Rajasthan''s signature trio of baked wheat balls, panchmel lentils, and sweetened crushed wheat with ghee.', 'राजस्थान का प्रसिद्ध व्यंजन — सेंकी हुई बाटी, पंचमेल दाल और घी में चूरा हुआ चूरमा।', 'राजस्थानचा प्रसिद्ध पदार्थ — भाजलेली बाटी, पंचमेल डाळ आणि तुपातला चूरमा।', 'https://www.youtube.com/results?search_query=dal+baati+churma+recipe+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('gatte-ki-sabzi', 'Gatte ki Sabzi', 'गट्टे की सब्ज़ी', 'गट्टे की भाजी', 'rajasthani', true, '{"lunch","dinner"}', 20, 30, 'medium', 2, 'roti', 320, 12, 30, 18, 5, 'Steamed besan dumplings simmered in a tangy yogurt-based curry, a Rajasthani staple.', 'उबले बेसन के गट्टे दही की तीखी-खट्टी ग्रेवी में पकाए हुए — राजस्थान का प्रमुख व्यंजन।', 'उकडलेले बेसनाचे गट्टे दही-आमटीत शिजवलेले — राजस्थानचा मुख्य पदार्थ.', 'https://www.youtube.com/results?search_query=gatte+ki+sabzi+recipe+rajasthani+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('ker-sangri', 'Ker Sangri', 'केर सांगरी', 'केर सांगरी', 'rajasthani', true, '{"lunch","dinner"}', 480, 25, 'medium', 2, 'bhakri', 180, 5, 20, 10, 6, 'Tangy desert beans and capers cooked with spices, a uniquely Rajasthani wild harvest dish.', 'मसालेदार खट्टी-तीखी केर और सांगरी — थार रेगिस्तान की जंगली सब्ज़ी।', 'मसालेदार आंबट-तिखट केर आणि सांगरी — थारच्या वाळवंटातील रानभाजी.', 'https://www.youtube.com/results?search_query=ker+sangri+recipe+rajasthani+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('pyaaz-kachori', 'Pyaaz Kachori', 'प्याज़ कचौरी', 'कांदा कचोरी', 'rajasthani', true, '{"breakfast","lunch"}', 30, 25, 'hard', 2, 'roti', 380, 7, 42, 22, 3, 'Flaky deep-fried pastry stuffed with spiced onion filling, a beloved Jodhpuri snack.', 'मसालेदार प्याज़ के भरावन वाली परतदार तली हुई कचौरी — जोधपुर की शान।', 'मसालेदार कांद्याच्या सारणाची खुसखुशीत तळलेली कचोरी — जोधपूरचा खास पदार्थ.', 'https://www.youtube.com/results?search_query=pyaaz+kachori+recipe+jodhpur+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
INSERT INTO dishes (slug, name_en, name_hi, name_mr, cuisine, is_veg, meal_types, prep_time_min, cook_time_min, difficulty, default_servings, default_accompaniment, calories, protein_g, carbs_g, fat_g, fiber_g, description_en, description_hi, description_mr, youtube_url, is_custom, illustration_url) VALUES ('laal-maas', 'Laal Maas', 'लाल मांस', 'लाल मांस', 'rajasthani', false, '{"dinner"}', 20, 60, 'medium', 2, 'roti', 480, 35, 8, 35, 2, 'Fiery red mutton curry made with Mathania chillies and yogurt, the pride of Rajput cuisine.', 'मथानिया मिर्च और दही से बना तीखा लाल मटन — राजपूती खाने की शान।', 'मथानिया मिरची आणि दह्यापासून बनवलेले तिखट लाल मटण — राजपूत खाद्यपरंपरेचा अभिमान.', 'https://www.youtube.com/results?search_query=laal+maas+recipe+rajasthani+recipe', false, NULL) ON CONFLICT (slug) DO NOTHING;
